/* generated by tools/make_voices.py: voice sprite timings and lip-sync envelopes (30 fps) */
const VOICE_DATA = {"file":"voice/ep02.mp3","lines":{"ep02_001":{"who":"TAKUTO","text":"Previously. The sky cracked open over the crossing in Nerima, and I fell into another world.","mono":true,"off":0.25,"dur":6.016,"env":"0127764256984531332110000000556512997777610122876500110579500253443221320111676634434434444545455543344555543332111000000000155666521118765544423134445554244322443321000000000000000"},"ep02_002":{"who":"TAKUTO","text":"I pulled an axe out of a grave that nobody could move for three hundred years.","mono":true,"off":6.666,"dur":4.48,"env":"036401149982773304665410243554213210124666543222100034301345556731555342011421344444321110221001033433343312321112333200000222000000000"},"ep02_003":{"who":"TAKUTO","text":"A girl named Nemu died to protect me. And something inside the axe asked me what I wanted to break.","mono":true,"off":11.546,"dur":6.357,"env":"01321389997665554454222454555444443311355554322201210121032540000111000000000000000002543435965202643113442333544442133213444310221023444242000332222343443322333221012102554210000000000000000"},"ep02_004":{"who":"TAKUTO","text":"I told it. Everything that's in the way.","mono":true,"off":18.3033,"dur":2.261,"env":"03663053289982576100000589226631154444456503334444345543110000000000"},"ep02_005":{"who":"AKURO","text":"You're not sleeping, boy.","mono":true,"off":20.9647,"dur":1.515,"env":"0136987764223324643225565642366655433221100000"},"ep02_006":{"who":"TAKUTO","text":"Neither are you, apparently.","mono":false,"off":22.8793,"dur":1.621,"env":"0356752988776522355423102325555531012110000000000"},"ep02_007":{"who":"AKURO","text":"I slept for three hundred years. I'm catching up on being awake.","mono":true,"off":24.9007,"dur":4.629,"env":"0267764434347985201113553100133456445633788744774222245766533221221100000025676532111346652134444564355431245533234555444336553421000000000"},"ep02_008":{"who":"TAKUTO","text":"Can everyone hear you?","mono":false,"off":29.93,"dur":1.323,"env":"0144320693246534443213443322222100000000"},"ep02_009":{"who":"AKURO","text":"Only you. Lucky boy.","mono":true,"off":31.6527,"dur":1.792,"env":"025899567756543458864311368741123633136998754321100000"},"ep02_010":{"who":"SIEG","text":"Talking to your axe again?","mono":false,"off":33.8447,"dur":1.813,"env":"0297631466665327667664100256542013226665476654332220000"},"ep02_011":{"who":"TAKUTO","text":"It started it.","mono":false,"off":36.058,"dur":1.045,"env":"03513430899998666424321000000000"},"ep02_012":{"who":"SIEG","text":"Get some sleep. Ashford's half a day's walk, and the Guild doesn't like people who show up yawning.","mono":false,"off":37.5033,"dur":5.803,"env":"0495233487754332577775200000000000000177754431077654312376541664676666545677665420000000000002898865468765565531775574336666410001975116666786433476666510057787665443221100000"},"ep02_013":{"who":"NEMU","text":"Five more minutes...","mono":false,"off":43.706,"dur":1.365,"env":"00019988887100988877787343100044420000000"},"ep02_014":{"who":"SIEG","text":"You've been asleep for six hours.","mono":false,"off":45.4713,"dur":2.112,"env":"0698765765565221677654100000001886321663112576666654433322210000"},"ep02_015":{"who":"NEMU","text":"Then five more hours.","mono":false,"off":47.9833,"dur":1.515,"env":"0059976311016555553002555300365431100002433000"},"ep02_016":{"who":"TAKUTO","text":"So this is a town.","mono":false,"off":49.898,"dur":1.28,"env":"001565389422532530112555553211000000000"},"ep02_017":{"who":"TAKUTO","text":"I was expecting more... dragons.","mono":false,"off":51.578,"dur":2.048,"env":"01476746614410993001655556766543220000001377786522211102100000"},"ep02_018":{"who":"SIEG","text":"Dragons are more of a southern thing.","mono":false,"off":54.026,"dur":2.432,"env":"0499766448766676420000006899976556541002667743227655777763116765432211000"},"ep02_019":{"who":"TAKUTO","text":"That was a joke.","mono":false,"off":56.858,"dur":1.131,"env":"0059964774595323449986320001000000"},"ep02_020":{"who":"SIEG","text":"So was mine. Mostly.","mono":false,"off":58.3887,"dur":1.792,"env":"023987677557876655666666554000008997777331156543220000"},"ep02_021":{"who":"CROWD2","text":"Is that the Headsman's Axe? On that boy's shoulder?","mono":false,"off":60.5807,"dur":2.795,"env":"088322996136424763224443322365554201212100036555774212555543222255442232211000000000"},"ep02_022":{"who":"CROWD","text":"Can't be. Nobody could pull it out.","mono":false,"off":63.7753,"dur":2.411,"env":"0117999730100687643221356778994387554111420001156555355442210022100000000"},"ep02_023":{"who":"CROWD2","text":"Look at his hair. Is he one of the Ashveils?","mono":false,"off":66.586,"dur":2.475,"env":"028941776852112555555431015522113555366452343367863221044333321211000000000"},"ep02_024":{"who":"TAKUTO","text":"Everyone's staring.","mono":false,"off":69.4607,"dur":1.195,"env":"058526976766444305977653211110000000"},"ep02_025":{"who":"NEMU","text":"You're carrying a legend around like a bag of groceries.","mono":false,"off":71.0553,"dur":3.797,"env":"004103228899987654543356741451222112000000774986532100020000000000000153365058665555124000204555234421000000233100"},"ep02_026":{"who":"TAKUTO","text":"It's heavy. Where else am I supposed to put it?","mono":false,"off":75.2527,"dur":2.517,"env":"0420211369823532100002445567764222344343442222002443210110115512100000000000"},"ep02_027":{"who":"NEMU","text":"Most people would put it in a museum.","mono":false,"off":78.17,"dur":2.283,"env":"004996352210338502443311540003118622100000000049887777464344311100000"},"ep02_028":{"who":"VENDOR","text":"Skewers! Fresh skewers! Rift-boar, still warm!","mono":false,"off":80.8527,"dur":2.56,"env":"02302898765532101974322201687553332213675100016665432202654434676543222110000"},"ep02_029":{"who":"NEMU","text":"Takuto.","mono":false,"off":83.8127,"dur":0.96,"env":"00327994021896061665432100000"},"ep02_030":{"who":"TAKUTO","text":"No.","mono":false,"off":85.1727,"dur":0.619,"env":"0145899876432000000"},"ep02_031":{"who":"NEMU","text":"I died for you yesterday.","mono":false,"off":86.1913,"dur":1.621,"env":"0238400698777642102111055566427753532430221100000"},"ep02_032":{"who":"TAKUTO","text":"...How many?","mono":false,"off":88.2127,"dur":0.917,"env":"0013489966888664321100000000"},"ep02_033":{"who":"NEMU","text":"Four. For now.","mono":false,"off":89.53,"dur":1.131,"env":"0001497776421001135556533211000000"},"ep02_034":{"who":"TAKUTO","text":"I don't even have money. I have two hundred yen and a receipt for cat food.","mono":false,"off":91.0607,"dur":4.608,"env":"0002669878873866457883246876532100000000000002776679710056366645866447522257665544312455434555544443200113201156520011155422100100000000000"},"ep02_035":{"who":"VENDOR","text":"Is that silver? Those little coins? I'll take 'em!","mono":false,"off":96.0687,"dur":2.731,"env":"0365389620222278887455431000579742775641243987765443210477641327774126654222110000"},"ep02_036":{"who":"TAKUTO","text":"...Four skewers, please.","mono":false,"off":99.1993,"dur":1.408,"env":"0000699633302666654210114554322110110000000"},"ep02_037":{"who":"NEMU","text":"Mm. Rift-boar.","mono":false,"off":101.0073,"dur":1.344,"env":"03697787776554200000088220312433211110000"},"ep02_038":{"who":"TAKUTO","text":"What's a Rift-boar?","mono":false,"off":102.7513,"dur":1.131,"env":"0137914674698210017775432211000000"},"ep02_039":{"who":"NEMU","text":"Don't ask while you're chewing.","mono":false,"off":104.282,"dur":1.515,"env":"0359962159975323320100567443035427764211000000"},"ep02_040":{"who":"TAKUTO","text":"Sieg. The Guild. What happens there?","mono":false,"off":106.1967,"dur":2.048,"env":"01233566421153117996443100000035433356600344321033211100000000"},"ep02_041":{"who":"SIEG","text":"Registration. They test your Brand, give you a rank, put your name in a very big book.","mono":false,"off":108.6447,"dur":5.184,"env":"089755556544114877764435644320000000000039962489643129653876666655542000005966876656766654100000000763787776566664215776544776656666414865433206642100010000"},"ep02_042":{"who":"SIEG","text":"Ranks go from F to S. F means you can carry luggage. S means kingdoms send you letters.","mono":false,"off":114.2287,"dur":5.824,"env":"0797663233008766521687510046651000156114775433322100000000067751068777775577511777522686666666654354332320000000000078531897766643011976656555643224766665666666653433222221000"},"ep02_043":{"who":"TAKUTO","text":"And you?","mono":false,"off":120.4527,"dur":0.789,"env":"058885347999753110000000"},"ep02_044":{"who":"SIEG","text":"A. Kingdoms send me invoices.","mono":false,"off":121.642,"dur":2.069,"env":"067765201297665765565222167655676410367665566664215533222100000"},"ep02_045":{"who":"TAKUTO","text":"Do they have records? Of Skyfallen?","mono":false,"off":124.1113,"dur":2.197,"env":"035399567893236986001454221320004424430577655110444322101000000000"},"ep02_046":{"who":"SIEG","text":"...Some.","mono":false,"off":126.7087,"dur":0.811,"env":"0485339987787766554210000"},"ep02_047":{"who":"TAKUTO","text":"My friend disappeared at that crossing two years ago. Haruki. Same crossing. Same bell.","mono":false,"off":127.9193,"dur":5.952,"env":"02566211597776347432510213566526301554100126643223443032253223554323311332211100000000000001499976775101125443321001234655554111578763332211100000000234555554256664311100000000000"},"ep02_048":{"who":"TAKUTO","text":"If something like me fell through, maybe he did too.","mono":false,"off":134.2713,"dur":2.795,"env":"031233594216444663113321055541000145542210000244454133233213431003134321000000000000"},"ep02_049":{"who":"SIEG","text":"Then you ask the Guild. I'm not the one who keeps that book.","mono":false,"off":137.466,"dur":3.349,"env":"05999887413666654410007865598777655432000000000489998765207777767899631288632430697422259642100100000"},"ep02_050":{"who":"NEMU","text":"...He changed the subject.","mono":false,"off":141.2153,"dur":1.515,"env":"0006604317999864320100143221552122322100001000"},"ep02_051":{"who":"TAKUTO","text":"I noticed.","mono":false,"off":143.13,"dur":0.875,"env":"266666679998453233100000000"},"ep02_052":{"who":"SIEG","text":"The Hunters' Guild of Ashford. Try not to break anything.","mono":false,"off":144.4047,"dur":3.669,"env":"089747977532877754336876666676300067520356554431067654310000000004797788765322586498775300167887521354322100000"},"ep02_053":{"who":"TAKUTO","text":"I only break things on purpose.","mono":false,"off":148.474,"dur":1.792,"env":"014543576665215976100035444344431126751021113221000000"},"ep02_054":{"who":"SIEG","text":"That's what worries me.","mono":false,"off":150.666,"dur":1.408,"env":"0698623417977410389877767777545865554210000"},"ep02_055":{"who":"CLERK","text":"Welcome to the Hunters' Guild of Ashford! Registration, quests, or complaints?","mono":false,"off":152.474,"dur":4.352,"env":"03898500376652444633565413665210166554362233545311001333321100000000488424752201666641126544300057543110012331003321003332210010000"},"ep02_056":{"who":"SIEG","text":"Registration. Two of them.","mono":false,"off":157.226,"dur":1.984,"env":"058653445542201665555332665544410000022976555433354333221000"},"ep02_057":{"who":"CLERK","text":"Wonderful! Names, please.","mono":false,"off":159.61,"dur":1.323,"env":"0698779500687677766531001365443332111000"},"ep02_058":{"who":"NEMU","text":"Nemu. Just Nemu.","mono":false,"off":161.3327,"dur":1.664,"env":"00169998789763100000001546544301777655433210000000"},"ep02_059":{"who":"TAKUTO","text":"Kirishima Takuto.","mono":false,"off":163.3967,"dur":1.6,"env":"011697797764888978712689501463036886331100000000"},"ep02_060":{"who":"CLERK","text":"Kiri... shima? What an unusual name. Where are you from, sir?","mono":false,"off":165.3967,"dur":2.795,"env":"003888667653112221677698741014966588667773156644554444322455554452003332122444321000"},"ep02_061":{"who":"TAKUTO","text":"Nerima.","mono":false,"off":168.5913,"dur":0.96,"env":"01468997546666676543110000000"},"ep02_062":{"who":"CLERK","text":"I don't know where that is.","mono":false,"off":169.9513,"dur":1.152,"env":"16789766998788846877345654321111000"},"ep02_063":{"who":"SIEG","text":"He's Skyfallen.","mono":false,"off":171.5033,"dur":1.365,"env":"04976654322201665555641046655554333221000"},"ep02_064":{"who":"CLERK","text":"...Oh. Oh. I see.","mono":false,"off":173.2687,"dur":1.131,"env":"0378875138997435773111354433321000"},"ep02_065":{"who":"CLERK","text":"We have a form for that. It's a very long form.","mono":false,"off":174.7993,"dur":2.368,"env":"057883831007998875115736765541000150373289877965667754300055554332321000"},"ep02_066":{"who":"TAKUTO","text":"Of course you do.","mono":false,"off":177.5673,"dur":1.131,"env":"0441002389843213442245431101000000"},"ep02_067":{"who":"CLERK","text":"And your weapon, sir? We register those too. Please place it on the counter.","mono":false,"off":179.098,"dur":3.883,"env":"035676469710476531116655431025542687213631016525765431101045443210000005555310014655111145533343330012343320022211000"},"ep02_068":{"who":"TAKUTO","text":"Are you sure? It is a little heavy.","mono":false,"off":183.3807,"dur":1.941,"env":"04654564543378997521000474863354554553225872131100000000000"},"ep02_069":{"who":"CLERK","text":"Sir, I've weighed war hammers. I think I can handle an a...","mono":false,"off":185.722,"dur":2.859,"env":"01298873289941359977733358975325554343333121100026500652662054434654255554444433221000"},"ep02_070":{"who":"CLERK","text":"...ax...","mono":false,"off":188.9807,"dur":0.619,"env":"0477899985011110000"},"ep02_071":{"who":"CLERK","text":"Is that the Headsman's Axe?","mono":false,"off":189.9993,"dur":1.28,"env":"153299507755796234796533345432100110000"},"ep02_072":{"who":"TAKUTO","text":"People keep asking me that.","mono":false,"off":191.6793,"dur":1.621,"env":"0156412982011465104445644301444443243211000000000"},"ep02_073":{"who":"CLERK","text":"It was in the Barrow Fields! For three hundred years! We have a painting of it! In the lobby!","mono":false,"off":193.7007,"dur":4.48,"env":"055474388789515988789973000356665442012100054001367755875574134665665221046446624201116664123444442143210000000165455434666551132111000"},"ep02_074":{"who":"TAKUTO","text":"It was loose.","mono":false,"off":198.5807,"dur":0.917,"env":"0443553244698642111110000000"},"ep02_075":{"who":"NEMU","text":"He keeps saying that.","mono":false,"off":199.898,"dur":1.451,"env":"00094042796044335898766554554321002100000000"},"ep02_076":{"who":"CLERK","text":"I need to get the appraiser. Please don't move. Please don't put it down. Please don't pick it up either.","mono":false,"off":201.7487,"dur":5.163,"env":"03565678702517720266720005666642355443210000001666773202986324777666531000000046565310497620117462015555444433200000554552202653101320254651001334123221100"},"ep02_077":{"who":"TAKUTO","text":"Should I just hold it?","mono":false,"off":207.3113,"dur":1.259,"env":"00235797524763211156655323210000000000"},"ep02_078":{"who":"CLERK","text":"Hold it very calmly!","mono":false,"off":208.97,"dur":1.152,"env":"05882752179878511126775445433221000"},"ep02_079":{"who":"VALENTINE","text":"Did someone say... the Headsman's Axe?","mono":false,"off":210.522,"dur":2.283,"env":"059302328989986632226665432200442358312265442326654310011110000000000"},"ep02_080":{"who":"VALENTINE","text":"Valentine. Brand appraiser of the Ashford chapter. And this is Tofu.","mono":false,"off":213.2047,"dur":4.075,"env":"019996666642135544444430156666645300135676333443104320654233003200413330001222210000000000578689434323231221555200012211000"},"ep02_081":{"who":"TAKUTO","text":"The cube is called Tofu?","mono":false,"off":217.6793,"dur":1.515,"env":"0042116993694412499631135897521113221110000000"},"ep02_082":{"who":"VALENTINE","text":"He is white, he is square, and he does not like being dropped. What else would I call him?","mono":false,"off":219.594,"dur":4.267,"env":"00468944335788641021045644543016665433223532532663427766512430014444224555322000021000000000004737986332151444101135442122222100"},"ep02_083":{"who":"NEMU","text":"Fair.","mono":false,"off":224.2607,"dur":0.683,"env":"000119876543221000000"},"ep02_084":{"who":"VALENTINE","text":"Tofu reads Brands. The mark on your soul has a shape, a weight, a color. He measures all three.","mono":false,"off":225.3433,"dur":5.035,"env":"01256510024322443420200034433222221220000000000157799830144433222354432222222323233320002212433101100112422211000000002566543323322113332100012221111000"},"ep02_085":{"who":"VALENTINE","text":"Then he gives you a rank, and you spend the rest of your life complaining about it.","mono":false,"off":230.778,"dur":3.797,"env":"079885672049922435554267653211100000026877555007767664279525342134434665310011452100556775433303432111210120000000"},"ep02_086":{"who":"VALENTINE","text":"Ladies first. Little cat, step forward.","mono":false,"off":234.9753,"dur":2.56,"env":"02689974775420068875422310200357574021478761002331541000066653333311000000000"},"ep02_087":{"who":"NEMU","text":"I'm not little.","mono":false,"off":237.9353,"dur":1.045,"env":"00349877788654000288533210000000"},"ep02_088":{"who":"VALENTINE","text":"Tofu, if you please.","mono":false,"off":239.3807,"dur":1.621,"env":"2159986200045544244001342011445432221221100000000"},"ep02_089":{"who":"VALENTINE","text":"Nine Lives. Rank D. Lives remaining... two.","mono":false,"off":241.402,"dur":3.051,"env":"05899999887998875551242067642110047654332024677861531667766654333300000000625875321100000000"},"ep02_090":{"who":"VALENTINE","text":"Two? Darling, what have you been doing?","mono":false,"off":244.8527,"dur":2.091,"env":"062566544200068899975433333324323102411443245433222210000000000"},"ep02_091":{"who":"NEMU","text":"Dying, mostly.","mono":false,"off":247.3433,"dur":1.152,"env":"00797899776554457886255410221100000"},"ep02_092":{"who":"TAKUTO","text":"We're going to talk about that later.","mono":false,"off":248.8953,"dur":1.941,"env":"01453129976544223204236630132443200343112344321110000000000"},"ep02_093":{"who":"NEMU","text":"You're making the face.","mono":false,"off":251.2367,"dur":1.237,"env":"00598898970316654431114542100023221000"},"ep02_094":{"who":"VALENTINE","text":"And now, our Skyfallen woodcutter. Hold the axe. Breathe. Think of something you hate.","mono":false,"off":252.874,"dur":4.48,"env":"036887777776665355115665200355444444463101132122210000000000399841455166542001123200000566544300000046623324354200334333312343210021000"},"ep02_095":{"who":"TAKUTO","text":"Paperwork.","mono":false,"off":257.754,"dur":0.875,"env":"025888217986898630011000000"},"ep02_096":{"who":"VALENTINE","text":"Perfect.","mono":false,"off":259.0287,"dur":0.981,"env":"016899720186553010212211000000"},"ep02_097":{"who":"VALENTINE","text":"Tofu?","mono":false,"off":260.41,"dur":0.853,"env":"02279997310035443300000000"},"ep02_098":{"who":"VALENTINE","text":"Error?","mono":false,"off":261.6633,"dur":0.96,"env":"17899889755421000000000000000"},"ep02_099":{"who":"VALENTINE","text":"Tofu does not say error. Tofu has never said error. Tofu once appraised a dragon.","mono":false,"off":263.0233,"dur":4.843,"env":"01279710044156332665530133344332444332221000002167610044343216666224232233211233222211000000000002379610055246431321001444442203311244442012111000"},"ep02_100":{"who":"SIEG","text":"Maybe the cube is broken.","mono":false,"off":268.266,"dur":2.005,"env":"0797776566655741132587776655300000278654387767511474332210000"},"ep02_101":{"who":"VALENTINE","text":"Wash your mouth, Sieg Valen.","mono":false,"off":270.6713,"dur":1.984,"env":"035899524325556655553200002222444201106654433222221000000000"},"ep02_102":{"who":"VALENTINE","text":"The Brand is called Ruinbreaker. That much he could read. The rank, the limits, the ceiling... nothing.","mono":false,"off":273.0553,"dur":5.077,"env":"043047877664544301355511237776554143200022210000378415650153230134111355432221100000000364389875211015456665310340134444445433322320000000256410022221000"},"ep02_103":{"who":"VALENTINE","text":"Either your Brand is broken, little woodcutter, or it is bigger than the box we built to measure it.","mono":false,"off":278.5327,"dur":4.885,"env":"057824886467620167777666243510016777301133332223334323862011232222200000000000588884474620059514874155552058786101421530365310232555445322210021000"},"ep02_104":{"who":"AKURO","text":"Bigger. Obviously.","mono":true,"off":283.818,"dur":1.493,"env":"013697634665531135767732555553332343321100000"},"ep02_105":{"who":"TAKUTO","text":"Shut up.","mono":false,"off":285.7113,"dur":0.704,"env":"0123899798652001110000"},"ep02_106":{"who":"VALENTINE","text":"...I beg your pardon?","mono":false,"off":286.8153,"dur":1.515,"env":"0057893049894216750022688774244443200000000000"},"ep02_107":{"who":"TAKUTO","text":"Not you.","mono":false,"off":288.73,"dur":0.853,"env":"01468994013367753211100000"},"ep02_108":{"who":"VALENTINE","text":"Oh, I like him. I like him very much. Register him as unranked, and put a star next to his name.","mono":false,"off":289.9833,"dur":5.611,"env":"0678987506565565652010232332100035556764010566303654444443210003320000000000000279814454303431454432334334444355543200112420131334404555543333310121222323244433222221000"},"ep02_109":{"who":"CLERK","text":"We don't have a star.","mono":false,"off":295.994,"dur":1.045,"env":"03649776766262110666654333221000"},"ep02_110":{"who":"VALENTINE","text":"Draw one!","mono":false,"off":297.4393,"dur":1.024,"env":"0358899984477765443000000000000"},"ep02_111":{"who":"TAKUTO","text":"All of these are jobs?","mono":false,"off":298.8633,"dur":1.344,"env":"05897852266643753223776654211101210000000"},"ep02_112":{"who":"NEMU","text":"Fiend bounties. Lesser ones pay in copper. Greater ones pay in silver.","mono":false,"off":300.6073,"dur":5.44,"env":"00017999865300766654204011000122100000000000000000000000268623343553355554340222544554302224322003100000000000000000117984476235555343022444334443322154320021100000"},"ep02_113":{"who":"TAKUTO","text":"And the ones with the red seal?","mono":false,"off":306.4473,"dur":1.579,"env":"045676479876322610353256652133324332111000000000"},"ep02_114":{"who":"NEMU","text":"Calamity class. Those pay in gold, and funerals.","mono":false,"off":308.426,"dur":3.84,"env":"01154788877725202114322110122210000000000000000000025976443033466576664457765432111001000007831224896442210002331000"},"ep02_115":{"who":"TAKUTO","text":"What was the thing at the crossing?","mono":false,"off":312.666,"dur":1.557,"env":"01598466316510076655203111278753332211000000000"},"ep02_116":{"who":"NEMU","text":"A Shieldbearer is Lesser. The weakest kind.","mono":false,"off":314.6233,"dur":3.093,"env":"013434359976204755444431144312454123211000000000000000000002743993032623120213655532110002000"},"ep02_117":{"who":"TAKUTO","text":"That was the weakest kind?","mono":false,"off":318.1167,"dur":1.493,"env":"005996386319746851147442013666532211100000000"},"ep02_118":{"who":"NEMU","text":"Mm. You're going to have a very interesting life.","mono":false,"off":320.01,"dur":3.413,"env":"0226655555543210000000000000000000540398877643232235203100444433331000897442113430332222222210000000000"},"ep02_119":{"who":"TAKUTO","text":"This one. The big one with the horns. Morvudd?","mono":false,"off":323.8233,"dur":2.624,"env":"0059664137765446218731365444104311356654322112310000001356777523431100000000000"},"ep02_120":{"who":"SIEG","text":"Don't take that one.","mono":false,"off":326.8473,"dur":1.387,"env":"298876533378775311146876520687654444320000"},"ep02_121":{"who":"TAKUTO","text":"I wasn't going to. I was just reading it.","mono":false,"off":328.634,"dur":2.56,"env":"00565379735432898754442141554321100000015755312554310123445434321110000000000"},"ep02_122":{"who":"SIEG","text":"Then stop reading it.","mono":false,"off":331.594,"dur":1.472,"env":"069877643305976741057888767677665544212100000"},"ep02_123":{"who":"SIEG","text":"...Sorry. Old poster. Bad memories. Come on, the clerk has your star ready.","mono":false,"off":333.466,"dur":4.736,"env":"02338765655653016766641039766432047654100000576654787555665544443320000000000019886555555544333630229764201387546654332056555665566533332110000"},"ep02_124":{"who":"NEMU","text":"Four times.","mono":false,"off":338.602,"dur":1.067,"env":"00019889760252577764322211433100"},"ep02_125":{"who":"TAKUTO","text":"I'm keeping count.","mono":false,"off":340.0687,"dur":1.195,"env":"037987222782196652268875321002000000"},"ep02_126":{"who":"RIN","text":"Which one of you is the Skyfallen with the Headsman's Axe?","mono":false,"off":341.6633,"dur":2.859,"env":"04912422899983467886630265312433217777301376555445453025323662224655432354320001121000"},"ep02_127":{"who":"TAKUTO","text":"...Me.","mono":false,"off":344.922,"dur":0.683,"env":"046679998764321000000"},"ep02_128":{"who":"RIN","text":"Why do you have my hair?","mono":false,"off":346.0047,"dur":1.344,"env":"03789735566623465105655541124432211000000"},"ep02_129":{"who":"TAKUTO","text":"Why do you have mine?","mono":false,"off":347.7487,"dur":1.237,"env":"00389984444655672135655532110000000000"},"ep02_130":{"who":"CROWD","text":"Wait. Are those two siblings?","mono":false,"off":349.386,"dur":2.091,"env":"037999862000687447765532000214554312326632432111110110000000000"},"ep02_131":{"who":"CROWD2","text":"They have the same face when they're angry.","mono":false,"off":351.8767,"dur":2.24,"env":"01677534796225321134443320005533322110332334444433221222111000000000"},"ep02_132":{"who":"RIN","text":"We are NOT related.","mono":false,"off":354.5167,"dur":1.28,"env":"047798999998774001675666553233203100000"},"ep02_133":{"who":"TAKUTO","text":"Agreed. My sister is nicer.","mono":false,"off":356.1967,"dur":1.877,"env":"232225998778523586632365401456532356776532323211000000000"},"ep02_134":{"who":"RIN","text":"You have a sister?","mono":false,"off":358.474,"dur":1.109,"env":"0478679838622239722202644322000000"},"ep02_135":{"who":"TAKUTO","text":"No.","mono":false,"off":359.9833,"dur":0.619,"env":"0145899876432000000"},"ep02_136":{"who":"NEMU","text":"He does that.","mono":false,"off":361.002,"dur":1.045,"env":"00069258643205543221001000000000"},"ep02_137":{"who":"SIEG","text":"Rin Ashveil. C rank, the youngest in the chapter. She has been waiting three years for someone to pull that axe out.","mono":false,"off":362.4473,"dur":7.019,"env":"0697664103554443210766655555410000000233497666766654200000000000488785565465203676531436654100154321000000000000249997654367666556554556641116655555555544320265322765555442451015755546653000465301325644221010000"},"ep02_138":{"who":"RIN","text":"Four years. I was going to pull it out. I trained for it. I had a plan.","mono":false,"off":369.866,"dur":3.691,"env":"001599975566766644313676642287732200166673655433101000356223257677631112544431100344323515100044332222100000000"},"ep02_139":{"who":"TAKUTO","text":"It was loose.","mono":false,"off":373.9567,"dur":0.917,"env":"0443553244698642111110000000"},"ep02_140":{"who":"RIN","text":"It was NOT loose! I tried every morning! I tried with rope! I tried with my Brand!","mono":false,"off":375.274,"dur":4.608,"env":"0593385579987640358976434410466123267778345851378887676655444203562132566751252102877530000000356023156666214301544410365433222111000000000"},"ep02_141":{"who":"VALENTINE","text":"She tried with a horse once. The horse gave up first.","mono":false,"off":380.282,"dur":3.136,"env":"01246233478787523514421466542210344332112210000000363379976322045554155200002654322112101000000"},"ep02_142":{"who":"RIN","text":"Valentine!","mono":false,"off":383.818,"dur":0.896,"env":"059888999451576555542000000"},"ep02_143":{"who":"RIN","text":"Fine. You want to be a Hunter? Then prove the axe chose you. Training yard. Now.","mono":false,"off":385.114,"dur":4.331,"env":"0017977777776325644775222216786322676413343220000015977621269720563055520133033577653323433200324766655555544443002433221100000000"},"ep02_144":{"who":"TAKUTO","text":"I'm not fighting a girl over an axe.","mono":false,"off":389.8447,"dur":2.091,"env":"003677898411115978865445321356654445422344321344110002432000000"},"ep02_145":{"who":"RIN","text":"Good. You won't be fighting. You'll be losing.","mono":false,"off":392.3353,"dur":2.155,"env":"01899812336646984015311167665534443310364156446654333322110000000"},"ep02_146":{"who":"TAKUTO","text":"Sieg?","mono":false,"off":394.89,"dur":0.725,"env":"0012299987422753100000"},"ep02_147":{"who":"SIEG","text":"Go on. You need to learn what your Brand can and cannot do. Better from her than from a Fiend.","mono":false,"off":396.0153,"dur":5.76,"env":"02987655555555430068777653337777765556654223664267655555420128875555310267412786666542000038754221000000000000286556652237667568655541000000001887522776642111776543322211000"},"ep02_148":{"who":"NEMU","text":"I'll hold the skewers.","mono":false,"off":402.1753,"dur":1.323,"env":"0489631159878402533222167643321101322000"},"ep02_149":{"who":"TAKUTO","text":"They're my skewers.","mono":false,"off":403.898,"dur":1.173,"env":"017888669886332015665432111111000000"},"ep02_150":{"who":"NEMU","text":"Were.","mono":false,"off":405.4713,"dur":0.597,"env":"000998643211000000"},"ep02_151":{"who":"SIEG","text":"Rules. No killing, no maiming, no damage to the Guild walls. Valentine is still angry about last spring.","mono":false,"off":406.4687,"dur":7.317,"env":"1897655554443322100006665520126755555444100000007766555544445544443100000002765555325544445443320134553375554344555332211232100000000000003875545454227655555311443210565300255555345443243265420145544322223002654321110000"},"ep02_152":{"who":"VALENTINE","text":"Eleven thousand crowns of stonework!","mono":false,"off":414.186,"dur":2.411,"env":"0468899616785003777753345520112665544343223124405656665332211001000000000"},"ep02_153":{"who":"RIN","text":"Draw your axe, Skyfallen.","mono":false,"off":416.9967,"dur":1.493,"env":"016999878656653013341165652114664433332100000"},"ep02_154":{"who":"TAKUTO","text":"It's always drawn. It doesn't fit in a pocket.","mono":false,"off":418.89,"dur":2.731,"env":"0422420789955765341023666664221110000022169644541115744443111156530012110000000000"},"ep02_155":{"who":"SIEG","text":"Begin!","mono":false,"off":422.0207,"dur":0.832,"env":"0898878877887766655310000"},"ep02_156":{"who":"RIN","text":"Red Thread.","mono":false,"off":423.2527,"dur":0.853,"env":"06998322137987554132100000"},"ep02_157":{"who":"TAKUTO","text":"...What is this?","mono":false,"off":424.506,"dur":0.939,"env":"02347957632116642211110000000"},"ep02_158":{"who":"RIN","text":"My Brand. Every thread I tie moves with me. Pull, and you fall. Struggle, and you choke.","mono":false,"off":425.8447,"dur":4.992,"env":"047884059988888853058822674011399846776333355566777777324225200444332000000001189987741588777322158876543113443159841465431355545204525543210100000000"},"ep02_159":{"who":"AKURO","text":"Threads. How adorable. Break them.","mono":true,"off":431.2367,"dur":2.005,"env":"0012459977533332356665235777776444543114677520124542322100000"},"ep02_160":{"who":"TAKUTO","text":"Ruinbreaker.","mono":false,"off":433.642,"dur":1.024,"env":"0258888775289973023542100000000"},"ep02_161":{"who":"RIN","text":"He... cut them? No. He broke them.","mono":false,"off":435.066,"dur":1.835,"env":"00578840033792017787767777643651199971120454333200000000"},"ep02_162":{"who":"RIN","text":"You swing like a landslide.","mono":false,"off":437.3007,"dur":1.557,"env":"03652332149888767402655655553221343322220000000"},"ep02_163":{"who":"TAKUTO","text":"Thanks.","mono":false,"off":439.258,"dur":0.661,"env":"00099865512212110000"},"ep02_164":{"who":"RIN","text":"It wasn't a compliment. Landslides are slow.","mono":false,"off":440.3193,"dur":2.581,"env":"058237994487560226885113666542110000368878764415766662236433323665433211000000"},"ep02_165":{"who":"RIN","text":"Block this.","mono":false,"off":443.3007,"dur":0.896,"env":"058899961112896422222100000"},"ep02_166":{"who":"AKURO","text":"Ha! Didn't anyone tell you?","mono":true,"off":444.5967,"dur":1.685,"env":"002478996414765766788677642342378756442432222100000"},"ep02_167":{"who":"AKURO","text":"I don't defend, boy. I only destroy.","mono":true,"off":446.682,"dur":2.603,"env":"0177886662464126999987323889875542101466744479886435544442124777766422210000000"},"ep02_168":{"who":"RIN","text":"Yield.","mono":false,"off":449.6847,"dur":0.683,"env":"024688997754122100000"},"ep02_169":{"who":"TAKUTO","text":"...I yield.","mono":false,"off":450.7673,"dur":0.939,"env":"00379985346788975321100000000"},"ep02_170":{"who":"RIN","text":"You hit like a landslide, and you defend like a sheet of paper.","mono":false,"off":452.106,"dur":3.349,"env":"03552379400356403655555555343144433333100000466556326211265554445410323332233113000134420012110000000"},"ep02_171":{"who":"RIN","text":"Whatever that axe is, it isn't yours yet.","mono":false,"off":455.8553,"dur":2.283,"env":"037437962794487624665302226665323100574873475134566655221353210010000"},"ep02_172":{"who":"NEMU","text":"Are you dead?","mono":false,"off":458.538,"dur":0.96,"env":"00289742277500565432220210000"},"ep02_173":{"who":"TAKUTO","text":"Only my pride.","mono":false,"off":459.898,"dur":1.173,"env":"058998998789881123997643211000000000"},"ep02_174":{"who":"NEMU","text":"That one doesn't come back. Trust me.","mono":false,"off":461.4713,"dur":2.325,"env":"0057641069875477435312155552544321000100000000000121773433121322100000"},"ep02_175":{"who":"TAKUTO","text":"I tried to block. The axe just... wouldn't. It slid off her knife like it didn't want to.","mono":false,"off":464.1967,"dur":5.44,"env":"00035413377663562146777743000012331345542013300233212210000000000013699243210000000000162143313577477654113444444444320003332022103423323344432003122100000000000000"},"ep02_176":{"who":"VALENTINE","text":"Because it didn't want to, darling.","mono":false,"off":470.0367,"dur":2.155,"env":"16122895569300397196214468994200341443126677653333223200000000000"},"ep02_177":{"who":"VALENTINE","text":"Every Brand has a price. Nine Lives has a count. Afterimage has a delay. Red Thread snaps if she loses her focus.","mono":false,"off":472.5913,"dur":6.72,"env":"0584146630377666652433410114543221122100000000003789989988776655522213333011444432011000000000897401236565413313324413645566643322100000259972001147741254355543012231342443565322331330036540012210121000"},"ep02_178":{"who":"VALENTINE","text":"Ruinbreaker breaks anything it strikes with intent. Shields. Armor. Barriers. Other Brands.","mono":false,"off":479.7113,"dur":5.205,"env":"0278888872776111551056511221467640344313441355420121041234311144321011000000000000245466654331022100000058999776433200455544333223102551563014443322222221000"},"ep02_179":{"who":"VALENTINE","text":"And in exchange, it will never, ever stand between you and a blow.","mono":false,"off":485.3167,"dur":3.584,"env":"058787960244154766665542312312566777740243200000299237467226555532323155555445664323433004555322210000000000"},"ep02_180":{"who":"TAKUTO","text":"So I can only attack.","mono":false,"off":489.3007,"dur":1.408,"env":"0134779971176666665555402335652100000000000"},"ep02_181":{"who":"SIEG","text":"So you have to be faster than everything that wants to hit you. Or smarter.","mono":false,"off":491.1087,"dur":4.331,"env":"0239878887631027677620057655432027876557762005754677414766676631367654330177449620027765432000000000005887644333498666654233221000"},"ep02_182":{"who":"TAKUTO","text":"I'm neither.","mono":false,"off":495.8393,"dur":0.875,"env":"389987788889457532100000000"},"ep02_183":{"who":"SIEG","text":"Not yet.","mono":false,"off":497.114,"dur":0.981,"env":"069976663158877676531222110000"},"ep02_184":{"who":"SIEG","text":"In three days the Guild holds its licensing exam in the Bramble Wastes. Teams of two. Survive, and you're a Hunter.","mono":false,"off":498.4953,"dur":7.68,"env":"068731258655476655665431006642277555554431675565346213246655543246532255655543445765554444200267664207665555455544665332231012220000000000002298766664464200328766533200000000000229877855555555410000000047877876554238654221432210000"},"ep02_185":{"who":"TAKUTO","text":"Teams. Then Nemu and I...","mono":false,"off":506.5753,"dur":1.856,"env":"03447888755353019966667777766665553446897411100000000000"},"ep02_186":{"who":"VALENTINE","text":"Ah. About that. Teams are assigned by the appraiser. Rank with rank, gap with gap.","mono":false,"off":508.8313,"dur":4.523,"env":"1677877528751037654300220024167999545564664555566303544134400125555342222200000000000025999741136212377654301003643200042001554321000000"},"ep02_187":{"who":"VALENTINE","text":"And the only applicant this season who might survive standing next to an ERROR...","mono":false,"off":513.754,"dur":3.989,"env":"048766149877876530675300130133200242322233322132321045555553003335203655444023303544433334343001213133333432211100000000"},"ep02_188":{"who":"TAKUTO","text":"No.","mono":false,"off":518.1433,"dur":0.619,"env":"0145899876432000000"},"ep02_189":{"who":"VALENTINE","text":"Is a certain C rank with very red threads.","mono":false,"off":519.162,"dur":2.688,"env":"065486433699830387332255664365542110154011199776664366510011366533110110000000000"},"ep02_190":{"who":"TAKUTO","text":"Absolutely not.","mono":false,"off":522.25,"dur":1.216,"env":"1579313437558632345555654210000000000"},"ep02_191":{"who":"RIN","text":"ABSOLUTELY NOT!","mono":false,"off":523.866,"dur":1.195,"env":"047822346979962256666655432101100000"},"ep02_192":{"who":"NEMU","text":"She heard that from across the yard.","mono":false,"off":525.4607,"dur":2.048,"env":"02336522899920145321000000000067712155535310443554321100011000"},"ep02_193":{"who":"SIEG","text":"Ha! This is going to be a wonderful exam.","mono":false,"off":527.9087,"dur":2.773,"env":"029877665310186436764059767763275777751016766666655557411476300575454797654321100000"},"ep02_194":{"who":"SIEG","text":"Again. When I swing, you move. Not your axe. You.","mono":false,"off":531.082,"dur":3.179,"env":"068798876655668766687444238776666665797887776653100000000997523885106776520243310017996542210000"},"ep02_195":{"who":"TAKUTO","text":"I moved last time.","mono":false,"off":534.6607,"dur":1.323,"env":"1566668898311597653430236544211000000000"},"ep02_196":{"who":"SIEG","text":"You moved your eyebrows. That is not dodging.","mono":false,"off":536.3833,"dur":2.816,"env":"0999987665522874103566654476654555543210000000488539765987554101129766665344432210000"},"ep02_197":{"who":"SIEG","text":"Afterimage.","mono":false,"off":539.5993,"dur":0.981,"env":"068873217998888866555542200000"},"ep02_198":{"who":"TAKUTO","text":"Two swings. You swung twice.","mono":false,"off":540.9807,"dur":1.792,"env":"014765333137976544321342220575443110699631000110000000"},"ep02_199":{"who":"SIEG","text":"Once. My Brand swings the second time for me, a heartbeat later, from the same angle.","mono":false,"off":543.1727,"dur":5.227,"env":"4987665233321006778646876666653332287666664027633267401766334865666521555544430000000002774587652000864115777665655410000000199977533278777620477664232210000"},"ep02_200":{"who":"SIEG","text":"Everyone you fight will have a trick like that. You can't block it. So you read it.","mono":false,"off":548.7993,"dur":4.672,"env":"058657765656666641104655542005666675464124376200266543000675544121000000000685139865323267655554005642210000000023788777666677676434310220000"},"ep02_201":{"who":"TAKUTO","text":"How?","mono":false,"off":553.8713,"dur":0.619,"env":"0016899877643100000"},"ep02_202":{"who":"SIEG","text":"Watch the shoulders, not the blade. The blade lies. The shoulders never do.","mono":false,"off":554.89,"dur":4.715,"env":"0786651133047544586556566655320000586520564167666665453210000000685697666644766555554444332000000000486443976665776545987654665423654332110000"},"ep02_203":{"who":"TAKUTO","text":"You sound like a fortune cookie.","mono":false,"off":560.0047,"dur":1.835,"env":"00244433987765565315210057740223443023740012110000000000"},"ep02_204":{"who":"SIEG","text":"I don't know what that is, but I'm choosing to be flattered.","mono":false,"off":562.2393,"dur":3.307,"env":"0698986447777776400048762268877644432000000000989988885155439878768767622867886211588776554332100000"},"ep02_205":{"who":"NEMU","text":"Sieg. Is he getting better?","mono":false,"off":565.946,"dur":1.728,"env":"0122349865420200000006532622587556554065443211110000"},"ep02_206":{"who":"SIEG","text":"He's getting hit less. That's the same thing, at the start.","mono":false,"off":568.074,"dur":3.328,"env":"0898646755567769620267666543222100000000068632210775225766666410666655554101552056332058654332010000"},"ep02_207":{"who":"TAKUTO","text":"Why are you helping me?","mono":false,"off":571.802,"dur":1.344,"env":"01489878864454235884004444332111000000000"},"ep02_208":{"who":"SIEG","text":"Because a long time ago, somebody taught me the same thing, and I didn't listen.","mono":false,"off":573.546,"dur":4.565,"env":"08629965866776655555643276566664357655541000000133786655545652125842047646533277666631057765444200000000068777774387575214785332232210000"},"ep02_209":{"who":"TAKUTO","text":"What happened?","mono":false,"off":578.5113,"dur":0.981,"env":"002799344677600443322110000000"},"ep02_210":{"who":"SIEG","text":"...Again. From the top.","mono":false,"off":579.8927,"dur":1.579,"env":"079976766666666654201498877523379766543100000000"},"ep02_211":{"who":"NEMU","text":"He changed the subject.","mono":false,"off":581.8713,"dur":1.515,"env":"0057033179998753210100034322553122322210001000"},"ep02_212":{"who":"TAKUTO","text":"Three times today.","mono":false,"off":583.786,"dur":1.301,"env":"0002777323899876533025448764211100000000"},"ep02_213":{"who":"VALENTINE","text":"You brought me a boy with the Headsman's Axe and didn't warn me.","mono":false,"off":585.4873,"dur":3.093,"env":"005511988415666401676776652330132224512325443510654320011232025513523311335554332111100000000"},"ep02_214":{"who":"SIEG","text":"Would you have believed me?","mono":false,"off":588.9807,"dur":1.536,"env":"07976566556668755300877666666664211565433210000"},"ep02_215":{"who":"VALENTINE","text":"I'd have worn a better coat.","mono":false,"off":590.9167,"dur":1.941,"env":"08998359413579999875344200887545420111466432002421000000000"},"ep02_216":{"who":"VALENTINE","text":"Sieg. Do you know why that axe was in a grave?","mono":false,"off":593.258,"dur":2.645,"env":"02355888741101455799988985367767337640079651023044445542026766533221000000000000"},"ep02_217":{"who":"SIEG","text":"The stories say the Headsman buried it with himself.","mono":false,"off":596.3033,"dur":3.243,"env":"05964219876766776532268666764100277569755444886555400000009766667657510158727876432278643210000000"},"ep02_218":{"who":"VALENTINE","text":"The stories are polite. The Guild archive is not. Three hundred years ago, something called the Crimson Calamity burned four cities to the ground.","mono":false,"off":599.946,"dur":7.488,"env":"044540587776764345201144454421001000000034049766131876301123332022325554322100100000000000000125774357744312554233013332221013254202444111441030011566333234301134455554313320036444442100045442233341322120311220144432222221000"},"ep02_219":{"who":"VALENTINE","text":"The Headsman didn't kill it. He couldn't. So he sealed it, into the only thing he owned that could hold it.","mono":false,"off":607.834,"dur":5.077,"env":"033349922517655524624410112544322002000000033012594243201100000000000236556445535665214320110352222530777667653003434334335544442152001311145331121001000"},"ep02_220":{"who":"SIEG","text":"His axe.","mono":false,"off":613.3113,"dur":0.875,"env":"019866555555431122333210000"},"ep02_221":{"who":"VALENTINE","text":"And today, while Tofu was reading that boy's Brand, something inside it looked back at him.","mono":false,"off":614.586,"dur":4.757,"env":"05873352788766543135640041168721015424432146541444434300055655423001555433333210000000001349851056653586554456551441125300200575200121202222100"},"ep02_222":{"who":"SIEG","text":"...He talks to it. He thinks we don't notice.","mono":false,"off":619.7433,"dur":2.453,"env":"05984369775213302787766531100000007973877433157657654467666644333222210000"},"ep02_223":{"who":"VALENTINE","text":"Then watch him, Sieg Valen. Very closely. If that thing ever opens its eyes...","mono":false,"off":622.5967,"dur":4.373,"env":"047888689993025234542342542110576543333332046556500104543123012221000000000034004883000566304651364036661013433220333433222221121000"},"ep02_224":{"who":"SIEG","text":"I know what the Guild does with Branded who lose control.","mono":false,"off":627.37,"dur":3.669,"env":"068898665655652003764349765666411765555433100387420038766666565432000000001998877666542017764433876543221100000"},"ep02_225":{"who":"VALENTINE","text":"Vesper does it. Let's make sure she never has to.","mono":false,"off":631.4393,"dur":2.709,"env":"0159633103541366522432000001466302217531132244221445444143212355411102221100000000"},"ep02_226":{"who":"SIEG","text":"Again, Takuto! Shoulders, not the blade!","mono":false,"off":634.5487,"dur":2.901,"env":"0587686655555212776630159752257666544310000002439766657665532077652036537776544332110000"},"ep02_227":{"who":"NEMU","text":"You're still mad.","mono":false,"off":637.85,"dur":1.024,"env":"0009955430499866664432221121000"},"ep02_228":{"who":"RIN","text":"I'm not mad. I'm practicing.","mono":false,"off":639.274,"dur":1.685,"env":"047999885268777666422146640115642002334434322100000"},"ep02_229":{"who":"NEMU","text":"You're practicing being mad.","mono":false,"off":641.3593,"dur":1.707,"env":"0077014399710055654356533137898777866431111210000000"},"ep02_230":{"who":"RIN","text":"...My brother was a Hunter. B rank. He used to walk me out to the Barrow Fields to look at that axe.","mono":false,"off":643.466,"dur":5.483,"env":"036778720798718986478447632277871424544321000006777637654441010000000000077788441475799400677777403234622866777763111555543133034545511430144424443200012322000000000"},"ep02_231":{"who":"RIN","text":"He said whoever pulled it out would be strong enough to protect everyone. He said it like a fairy tale.","mono":false,"off":649.3487,"dur":5.611,"env":"0037744449777221479996267200037783694666665310154135334313767766666553110220143033531011056424654443333200000000000563446985576024555213211145544441212443322110000000000"},"ep02_232":{"who":"NEMU","text":"What happened to him?","mono":false,"off":655.3593,"dur":1.216,"env":"0029732338992079751744411565432100000"},"ep02_233":{"who":"RIN","text":"A Greater Fiend, four years ago. The day after, I started trying to pull out the axe. Every morning.","mono":false,"off":656.9753,"dur":5.781,"env":"045115998736611115666566552111136677544665433421343322200000000362788776566411136633553343265555102145454120000565554410243034432100123320000004541255455444433221210000000000"},"ep02_234":{"who":"RIN","text":"And then some idiot from another world walks past and it just... comes out. Like it was waiting for him.","mono":false,"off":663.1567,"dur":5.909,"env":"0479988975545778720694567882011367777776287535787773223688620132012255554321230135652003475323302000000000013889974697654410121000003677314525432487773545411143223333210000000000"},"ep02_235":{"who":"NEMU","text":"Maybe it was.","mono":false,"off":669.466,"dur":0.981,"env":"000799914765201565432212332000"},"ep02_236":{"who":"RIN","text":"That's not comforting.","mono":false,"off":670.8473,"dur":1.237,"env":"05872242899730125776311655443331000000"},"ep02_237":{"who":"NEMU","text":"It wasn't meant to be. He's an idiot, but he jumped in front of a Fiend for me yesterday. And for a cat, the day before.","mono":false,"off":672.4847,"dur":9.131,"env":"0131004543252003554203120333110000000000000000000000000000004753265300796253221000110000000000001322420233165542102035421104544402311000566554322210023444332333222121101111000000000000000000000000000000000000562113443001123443210001100000000000044245433022211013222111000000"},"ep02_238":{"who":"RIN","text":"...For a cat?","mono":false,"off":682.0153,"dur":0.853,"env":"02128998411575443101210000"},"ep02_239":{"who":"NEMU","text":"Mm. He's that kind of idiot.","mono":false,"off":683.2687,"dur":2.261,"env":"02397778777644210000000000008965406752002256552114962312100030000000"},"ep02_240":{"who":"RIN","text":"...I'm still going to beat him at the exam.","mono":false,"off":685.93,"dur":2.219,"env":"0477784341298852289765632331045430215554201446411224543222210000000"},"ep02_241":{"who":"NEMU","text":"You're on his team.","mono":false,"off":688.5487,"dur":1.045,"env":"00198644896774330524864321010000"},"ep02_242":{"who":"RIN","text":"Then I'll beat him from the same team.","mono":false,"off":689.994,"dur":2.005,"env":"0599775789942018752224655211666653443765555222254332221000000"},"ep02_243":{"who":"TAKUTO","text":"The book. The one with every Hunter's name in it. Does it have Skyfallen too?","mono":false,"off":692.3993,"dur":4.117,"env":"0211049972000024224433332010343123221133320112211132222222221110000000000000032242223331222202344320002322222102123220000000"},"ep02_244":{"who":"CLERK","text":"It does, sir. But the Skyfallen pages are... sealed.","mono":false,"off":696.9167,"dur":2.923,"env":"0300799732228888852740452111898850088788752215776216753365555443100000001126676433310000"},"ep02_245":{"who":"TAKUTO","text":"Sealed by who?","mono":false,"off":700.2393,"dur":1.088,"env":"002326898321997543366421100000000"},"ep02_246":{"who":"CLERK","text":"By order of Saint Lumen. The capital. Every Skyfallen is reported there, and the pages come back with a gold seal on them.","mono":false,"off":701.7273,"dur":6.933,"env":"0677522899768884122287631368876765544200000000040137871065786531000000039825885320188987100876677653452136400006875673102655444321455530201777512477422011565431655431004404201675551022223555433234433321112100"},"ep02_247":{"who":"TAKUTO","text":"I'm looking for one person. Shinjo Haruki. Sixteen. Black hair. He'd have come through about two years ago.","mono":false,"off":709.0607,"dur":7.168,"env":"000477766931266511585367655211476433321000000000024546677634698873236766455420111332111000013349501331034433211100000468874011146655311100000000056672012675540113556664236654100142344323444433331133221000000000000000"},"ep02_248":{"who":"CLERK","text":"I'm sorry, sir. I'm not allowed to break the seal.","mono":false,"off":716.6287,"dur":2.283,"env":"056632239877776111576544200476688777566773130475300043111144442221000"},"ep02_249":{"who":"VALENTINE","text":"She isn't. I, however, have terrible manners.","mono":false,"off":719.3113,"dur":2.773,"env":"013342597546662010004678763235555410432113520003114556403544555555432221122100000000"},"ep02_250":{"who":"VALENTINE","text":"Tofu has a very good memory. He reads every Brand that passes through this hall. Including, two winters ago...","mono":false,"off":722.4847,"dur":6.08,"env":"023899211266422544441276566201573026655543322220000000000026536767406106961166400577665543420123762331334101331233310354332200000000004861217775264344106316542667532333333112332221000"},"ep02_251":{"who":"VALENTINE","text":"A boy with black hair and blue eyes. Frightened, polite, very cold hands. His Brand stopped Tofu's clock for three seconds.","mono":false,"off":728.9647,"dur":7.125,"env":"1641598898973640005764201114554334453044554544322222132000000000000499752005652001355566642000016655630211564441113333222323200000000000006430047777675451455200222565100442300126654101002300014432342420112222122100"},"ep02_252":{"who":"TAKUTO","text":"That's him. Where did he go?","mono":false,"off":736.49,"dur":1.6,"env":"005998405528865432225663644532168764221100000000"},"ep02_253":{"who":"VALENTINE","text":"Where every Skyfallen goes. A carriage came from Saint Lumen, with a golden sun on the door. He got in. He waved.","mono":false,"off":738.49,"dur":6.571,"env":"046407861155345124676510034433344214544322212220000000003102258777316402354530135334443124676653333322302697763155635534544334343302444432220000000000014128984135654432100000000044267654322210001000"},"ep02_254":{"who":"VALENTINE","text":"That is all I know, and I have already said too much in a building with very thin walls.","mono":false,"off":745.4607,"dur":4.331,"env":"0662345552377877755555443323100000000456976613776573353443540006235677551044244302665303333333100028544431000545443344322111122100"},"ep02_255":{"who":"TAKUTO","text":"Thank you.","mono":false,"off":750.1913,"dur":0.832,"env":"0019987611168754321100000"},"ep02_256":{"who":"VALENTINE","text":"Don't thank me. Pass the exam. Hunters can go anywhere. Even the capital.","mono":false,"off":751.4233,"dur":4.139,"env":"04774100046652103432012367435104543112344332223100000000000159782435434113541567534566534332221002454145433011343001212211000"},"ep02_257":{"who":"NEMU","text":"Can't sleep?","mono":false,"off":755.962,"dur":0.981,"env":"021799741222213564210021000000"},"ep02_258":{"who":"TAKUTO","text":"It's too quiet. In Nerima there's always a train somewhere.","mono":false,"off":757.3433,"dur":3.733,"env":"0312410436410119986432110000000000456556676534555454444321333222055553344322201212433333322224332211100000000000"},"ep02_259":{"who":"NEMU","text":"You miss it.","mono":false,"off":761.4767,"dur":0.96,"env":"00069877873322332102100000000"},"ep02_260":{"who":"TAKUTO","text":"I miss the cat. The rest of it I can live without.","mono":false,"off":762.8367,"dur":3.051,"env":"03556676441041011466542100000000003543899635115225532144411144444455211342044331100000000000"},"ep02_261":{"who":"NEMU","text":"Liar.","mono":false,"off":766.2873,"dur":0.725,"env":"0117988997544321100000"},"ep02_262":{"who":"TAKUTO","text":"...Maybe.","mono":false,"off":767.4127,"dur":0.789,"env":"013579999426643210000000"},"ep02_263":{"who":"NEMU","text":"The boy on the poster. Haruki.","mono":false,"off":768.602,"dur":2.475,"env":"143059778886531049755103155424424211100000000000000014998677401313211000000"},"ep02_264":{"who":"TAKUTO","text":"You saw that?","mono":false,"off":771.4767,"dur":0.981,"env":"014543323988835654321000000000"},"ep02_265":{"who":"NEMU","text":"I fell on it. It was very soggy.","mono":false,"off":772.858,"dur":2.347,"env":"02651112998666667533200200000000000003932855118666545433555632131000000"},"ep02_266":{"who":"TAKUTO","text":"He fed that cat every night on his way home. Then one night he didn't come home.","mono":false,"off":775.6047,"dur":4.629,"env":"0031113985116652001113454100034411333343333222223323102333221233321000000000000000244434554444443321001212412211123222113432100000000000000"},"ep02_267":{"who":"TAKUTO","text":"Everyone said he ran away. I didn't believe them. I kept going to the crossing.","mono":false,"off":780.634,"dur":4.971,"env":"000687249864777653543887534432455555544456664211100000000565269465206543465554210321000000000004650125960010287654452321320115777424442100000000000000"},"ep02_268":{"who":"TAKUTO","text":"And then the sky opened, and I thought... oh. Oh, that's where he went.","mono":false,"off":786.0047,"dur":3.947,"env":"00257887776761297877632688201444334445455111179974100000000000005899865432100357654226663051144444324432100110000000000"},"ep02_269":{"who":"NEMU","text":"And if he's here?","mono":false,"off":790.3513,"dur":1.024,"env":"0597783011057633211543321110000"},"ep02_270":{"who":"TAKUTO","text":"Then I find him. And I take him home.","mono":false,"off":791.7753,"dur":2.453,"env":"00476887622189887743542210000003558876146397401154542147775321000000000000"},"ep02_271":{"who":"NEMU","text":"...Sieg changed the subject again, didn't he. When you asked about going home.","mono":false,"off":794.6287,"dur":5.333,"env":"0012234996100442677876442000334234641143420023024433222100000000000038164211553200000000000000000000000000006989740288764122200422643003565555421136654210000000"},"ep02_272":{"who":"TAKUTO","text":"Twice.","mono":false,"off":800.362,"dur":0.683,"env":"011799865442111000000"},"ep02_273":{"who":"NEMU","text":"Then don't ask him. Ask me. I'll tell you the truth.","mono":false,"off":801.4447,"dur":3.691,"env":"015986698510588653330242333100000000179863334010332100000000000000000000026973033267885562270442187632011000000"},"ep02_274":{"who":"TAKUTO","text":"...Has anyone ever gone back?","mono":false,"off":805.5353,"dur":1.536,"env":"00066549777666666424311455554157631000000000000"},"ep02_275":{"who":"NEMU","text":"Go to sleep, Takuto.","mono":false,"off":807.4713,"dur":1.749,"env":"02999855754320477420010000000337750116404143221100000"},"ep02_276":{"who":"TAKUTO","text":"That's an answer, isn't it.","mono":false,"off":809.6207,"dur":1.515,"env":"0059812376767886234455320026743443211000000000"},"ep02_277":{"who":"NEMU","text":"It's a suggestion. You have an exam in three days and a partner who hates you.","mono":false,"off":811.5353,"dur":5.419,"env":"0111435332622536531320142100000000000000000000000000000068446991699843222788877654566302206877405654322211012210000000019780032576300354430055212553000232121000000"},"ep02_278":{"who":"TAKUTO","text":"Don't remind me.","mono":false,"off":817.354,"dur":1.131,"env":"0399851147555766655433211000000000"},"ep02_279":{"who":"AKURO","text":"Three hundred years in the dirt, and you're my first friend in centuries.","mono":true,"off":818.8847,"dur":4.736,"env":"00024466885333589746886422238999866653236778642137889875320000000257665997658986631101687887532111136887677556554233334665334343322221112211000"},"ep02_280":{"who":"TAKUTO","text":"We're not friends.","mono":false,"off":824.0207,"dur":1.088,"env":"015778997111189886543221321000000"},"ep02_281":{"who":"AKURO","text":"Not yet, boy. Not yet.","mono":true,"off":825.5087,"dur":1.728,"env":"0146776313797420147777744545556653102354432101221000"},"ep02_282":{"who":"SABLE","text":"Ruinbreaker.","mono":false,"off":827.6367,"dur":1.493,"env":"010224699754465431256643111113100000000000000"},"ep02_283":{"who":"SABLE","text":"...Let's see what it breaks first.","mono":false,"off":829.53,"dur":2.496,"env":"000035796435745743455333101343321123100255432111221000000000000000000000000"},"ep02_284":{"who":"TAKUTO","text":"Next time: the licensing exam in the Bramble Wastes.","mono":false,"off":832.426,"dur":3.328,"env":"0047821420289987311100016458998733345413354444222237665555444444104655555335542353210012000110000000"},"ep02_285":{"who":"TAKUTO","text":"I'm stuck on a team with Rin, I meet a guy whose head is on fire who says he's from Osaka...","mono":false,"off":836.154,"dur":5.781,"env":"024542330196102554410120233433333200013443211000000000002454444444651114444443332212222102344232223332200004434332221112212214332110122212002222122122133321000100000000000000"},"ep02_286":{"who":"TAKUTO","text":"...and the ground starts walking.","mono":false,"off":842.3353,"dur":1.707,"env":"0015778522898776644316542311367874011321101000000000"},"ep02_287":{"who":"TAKUTO","text":"Episode three. A Flame From Home.","mono":false,"off":844.442,"dur":2.219,"env":"0561144449984100124554311000004111136655543113333355532110000000000"}}};
